using Common.Models;

namespace Common.Services;

public interface IRideRepository {
	IEnumerable<Ride> Fetch();
	IEnumerable<Ride> Fetch(string clientUsername) => Fetch().Where(ride => ride.ClientUsername == clientUsername);
	Ride Fetch(int id) => Fetch().First(ride => ride.Id == id);
	int NextId => Fetch().Select(ride => ride.Id).DefaultIfEmpty(0).Max() + 1;

	void UpdateClientUsername(string oldUsername, string newUsername) {
		foreach (var ride in Fetch(oldUsername))
			ride.ClientUsername = newUsername;
	}

	void Add(Ride ride);
}

